// Pseudo enqueue (high level, non‑blocking semantics)
function enqueue(slot, payload){
  slot.payload = payload; // write payload
  slot.len = payload.length;
  slot.seq = slot.seq + 1; // release semantics
  clwb(&slot.payload); clwb(&slot.len); clwb(&slot.seq);
  sfence();
}
```

```javascript
// Pseudo dequeue
function dequeue(){
  if (ring.head.seq == ring.tail.seq) return null; // empty
  let s = ring.head; let payload = s.payload;
  // advance head after acquire read
  ring.head = next(s);
  s.done = true; clwb(&s.done); sfence();
  return payload;
}
```

## Why This Is Asked
Tests understanding of memory layout, overlap handling, and cache-friendly copy strategies in tight, real-world paths.

## Key Concepts
- Overlap-safe memmove
- Cache-friendly 64-byte blocks
- Alignment assumptions and tail handling
- Fallback to memcpy for tiny or unaligned data
- Microbenchmark plan to measure throughput vs standard memcpy

## Code Example
```c
#include <stddef.h>
#include <string.h>

void *memmove64(void *dst, const void *src, size_t n){
  unsigned char *d = (unsigned char*)dst;
  const unsigned char *s = (const unsigned char*)src;
  const size_t BLOCK = 64;

  if ((size_t)(d) <= (size_t)(s) || d >= s + n){
    while (n >= BLOCK){
      memcpy(d, s, BLOCK);
      d += BLOCK; s += BLOCK; n -= BLOCK;
    }
    if (n) memcpy(d, s, n);
  } else {
    d += n; s += n;
    while (n >= BLOCK){
      d -= BLOCK; s -= BLOCK;
      memcpy(d, s, BLOCK);
      n -= BLOCK;
    }
    if (n) memcpy(d - n, s - n, n);
  }
  return dst;
}
```

